#include <stdio.h>

int main(void) {
    int n;
    printf("Enter a number (1-20): ");
    scanf("%d", &n);

    /* Game 1: is it prime? */
    int isPrime = (n >= 2);
    for (int d = 2; d * d <= n; d++) {
        if (n % d == 0) {
            isPrime = 0;
            break;
        }
    }
    printf("%d is %s\n", n, isPrime ? "prime" : "not prime");

    /* Game 2: factorial */
    long long fact = 1;
    for (int i = 2; i <= n; i++) {
        fact = fact * i;
    }
    printf("%d! = %lld\n", n, fact);

    /* Game 3: reverse the digits */
    int temp = n;
    int reversed = 0;
    while (temp > 0) {
        int digit = temp % 10;
        reversed = reversed * 10 + digit;
        temp = temp / 10;
    }
    printf("Reversed: %d\n", reversed);

    return 0;
}

